
"use strict";

const welcome = document.getElementById("welcome");
const documentList = document.getElementById("document-list");
const listMessage = document.getElementById("list-message");
const uploadForm = document.getElementById("upload-form");
const uploadMessage = document.getElementById("upload-message");

const documentSearch = document.getElementById("document-search");
let searchTimer;

// Read the CSRF token generated by Spring Security.
function getCsrfToken() {
    const cookie = document.cookie
        .split("; ")
        .find((item) => item.startsWith("XSRF-TOKEN="));

    return cookie
        ? decodeURIComponent(cookie.substring("XSRF-TOKEN=".length))
        : null;
}

// Verify the login session and load the dashboard.
async function loadDashboard() {
    try {
        const userResponse = await fetch("/api/auth/me", {
            credentials: "same-origin",
            headers: {
                "Accept": "application/json"
            }
        });

        if (userResponse.status === 401 || userResponse.redirected) {
            window.location.href = "/login";
            return;
        }

        if (!userResponse.ok) {
            throw new Error("Could not verify your login.");
        }

        const user = await userResponse.json();
        welcome.textContent = `Signed in as ${user.email}`;

        await loadDocuments();
    } catch (error) {
        welcome.textContent = "Unable to verify your session.";
        documentList.replaceChildren();
        listMessage.textContent = error.message;
    }
}

// Load documents visible to the current user.

async function loadDocuments(keyword = "") {
    documentList.replaceChildren();
    listMessage.textContent = "";

    try {
        const url = keyword.trim()
            ? `/api/documents/search?keyword=${encodeURIComponent(keyword.trim())}`
            : "/api/documents";

        const response = await fetch(url, {
            credentials: "same-origin",
            headers: {
                "Accept": "application/json"
            }
        });

        if (response.status === 401 || response.redirected) {
            window.location.href = "/login";
            return;
        }

        if (!response.ok) {
            throw new Error(
                response.status === 403
                    ? "Access denied when loading documents."
                    : `Could not load documents (HTTP ${response.status}).`
            );
        }

        const documents = await response.json();

        if (!Array.isArray(documents) || documents.length === 0) {
            const empty = document.createElement("p");
            empty.className = "muted";
            empty.textContent = keyword.trim()
                ? "No matching documents found."
                : "No documents uploaded yet.";
            documentList.appendChild(empty);
            return;
        }

        documents.forEach((documentData) => {
            const item = document.createElement("article");
            item.className = "document-item";

            const title = document.createElement("strong");
            title.textContent = documentData.title || "Untitled document";

            const filename = document.createElement("p");
            filename.className = "muted";
            filename.textContent =
                documentData.filename ||
                documentData.originalFilename ||
                "File name unavailable";

            const details = document.createElement("p");
            details.className = "muted";
            details.textContent =
                `Size: ${documentData.sizeBytes ?? "Unknown"} bytes`;
				

				const downloadButton = document.createElement("button");
				downloadButton.type = "button";
				downloadButton.className = "dashboard-button";
				downloadButton.textContent = "Download";

				downloadButton.addEventListener("click", async () => {
				    downloadButton.disabled = true;
				    downloadButton.textContent = "Downloading...";
				    listMessage.textContent = "";

				    try {
				        const response = await fetch(
				            `/api/documents/${encodeURIComponent(documentData.id)}/download`,
				            {
				                method: "GET",
				                credentials: "same-origin"
				            }
				        );

				        if (response.status === 401 || response.redirected) {
				            window.location.href = "/login";
				            return;
				        }

				        if (!response.ok) {
				            throw new Error(
				                response.status === 404
				                    ? "Document not found or access denied."
				                    : `Download failed (HTTP ${response.status}).`
				            );
				        }

				        const blob = await response.blob();
				        const objectUrl = URL.createObjectURL(blob);
				        const link = document.createElement("a");

				        link.href = objectUrl;
				        link.download = documentData.filename
				            || documentData.originalFilename
				            || "document";

				        document.body.appendChild(link);
				        link.click();
				        link.remove();

				        setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
				    } catch (error) {
				        listMessage.textContent = error.message;
				    } finally {
				        downloadButton.disabled = false;
				        downloadButton.textContent = "Download";
				    }
				});


				item.append(title, filename, details, downloadButton);

				// Sharing controls for document owners.
				const shareSection = document.createElement("div");
				shareSection.style.marginTop = "16px";

				const recipientInput = document.createElement("input");
				recipientInput.type = "email";
				recipientInput.placeholder = "Recipient's registered email";
				recipientInput.maxLength = 254;
				recipientInput.className = "dashboard-input";
				recipientInput.setAttribute("aria-label", "Recipient email");

				const permissionSelect = document.createElement("select");
				permissionSelect.className = "dashboard-input";
				permissionSelect.setAttribute("aria-label", "Permission type");

				[
				    { value: "VIEW", label: "View only" },
				    { value: "EDIT", label: "Edit" }
				].forEach((optionData) => {
				    const option = document.createElement("option");
				    option.value = optionData.value;
				    option.textContent = optionData.label;
				    permissionSelect.appendChild(option);
				});

				const shareButton = document.createElement("button");
				shareButton.type = "button";
				shareButton.className = "dashboard-button";
				shareButton.textContent = "Share document";

				shareButton.addEventListener("click", async () => {
				    const email = recipientInput.value.trim();
				    const csrfToken = getCsrfToken();

				    if (!email) {
				        listMessage.textContent = "Enter the recipient's email.";
				        return;
				    }

				    if (!csrfToken) {
				        listMessage.textContent =
				            "Security token is missing. Refresh the page and try again.";
				        return;
				    }

				    shareButton.disabled = true;
				    listMessage.textContent = "";

				    try {
				        const response = await fetch(
				            `/api/documents/${encodeURIComponent(documentData.id)}/permissions`,
				            {
				                method: "POST",
				                credentials: "same-origin",
				                headers: {
				                    "Content-Type": "application/json",
				                    "Accept": "application/json",
				                    "X-XSRF-TOKEN": csrfToken
				                },
				                body: JSON.stringify({
				                    email: email,
				                    permissionType: permissionSelect.value
				                })
				            }
				        );

				        if (response.status === 401 || response.redirected) {
				            window.location.href = "/login";
				            return;
				        }

				        if (!response.ok) {
				            throw new Error(
				                `Sharing failed (HTTP ${response.status}). Check that you own the document and the recipient exists.`
				            );
				        }

				        recipientInput.value = "";
				        listMessage.textContent =
				            `Document shared with ${email} successfully.`;
				    } catch (error) {
				        listMessage.textContent = error.message;
				    } finally {
				        shareButton.disabled = false;
				    }
				});

				shareSection.append(
				    recipientInput,
				    permissionSelect,
				    shareButton
				);

				

				item.appendChild(shareSection);

				// List shared users and provide a revoke button.
				const permissionsSection = document.createElement("div");
				permissionsSection.style.marginTop = "16px";

				const permissionsHeading = document.createElement("h3");
				permissionsHeading.textContent = "Shared with";

				const permissionsList = document.createElement("div");
				permissionsList.className = "muted";
				permissionsList.textContent = "Loading permissions...";

				permissionsSection.append(permissionsHeading, permissionsList);
				item.appendChild(permissionsSection);

				async function loadPermissions() {
				    permissionsList.replaceChildren();

				    try {
				        const response = await fetch(
				            `/api/documents/${encodeURIComponent(documentData.id)}/permissions`,
				            {
				                credentials: "same-origin",
				                headers: { "Accept": "application/json" }
				            }
				        );

				        if (!response.ok) {
				            permissionsList.textContent =
				                response.status === 403 || response.status === 404
				                    ? "Permission details unavailable."
				                    : "Could not load shared users.";
				            return;
				        }

				        const permissions = await response.json();

				        if (!Array.isArray(permissions) || permissions.length === 0) {
				            permissionsList.textContent = "Not shared with anyone yet.";
				            return;
				        }

				        permissions.forEach((permission) => {
				            const row = document.createElement("div");
				            row.className = "document-item";

				            const userLabel = document.createElement("span");
				            userLabel.textContent =
				                `${permission.email} — ${permission.permissionType}`;

				            const revokeButton = document.createElement("button");
				            revokeButton.type = "button";
				            revokeButton.className = "dashboard-button";
				            revokeButton.textContent = "Revoke access";

				            revokeButton.addEventListener("click", async () => {
				                if (!window.confirm(
				                    `Revoke ${permission.email}'s access to this document?`
				                )) {
				                    return;
				                }

				                const csrfToken = getCsrfToken();

				                if (!csrfToken) {
				                    listMessage.textContent =
				                        "Security token missing. Refresh and try again.";
				                    return;
				                }

				                revokeButton.disabled = true;

				                try {
				                    const revokeResponse = await fetch(
				                        `/api/documents/${encodeURIComponent(documentData.id)}/permissions/${encodeURIComponent(permission.recipientId)}`,
				                        {
				                            method: "DELETE",
				                            credentials: "same-origin",
				                            headers: {
				                                "Accept": "application/json",
				                                "X-XSRF-TOKEN": csrfToken
				                            }
				                        }
				                    );

				                    if (revokeResponse.status === 401 ||
				                        revokeResponse.redirected) {
				                        window.location.href = "/login";
				                        return;
				                    }

				                    if (!revokeResponse.ok) {
				                        throw new Error(
				                            `Revocation failed (HTTP ${revokeResponse.status}).`
				                        );
				                    }

				                    listMessage.textContent =
				                        `Access revoked for ${permission.email}.`;

				                    await loadPermissions();
				                } catch (error) {
				                    listMessage.textContent = error.message;
				                } finally {
				                    revokeButton.disabled = false;
				                }
				            });

				            row.append(userLabel, document.createTextNode(" "), revokeButton);
				            permissionsList.appendChild(row);
				        });
				    } catch {
				        permissionsList.textContent = "Could not load shared users.";
				    }
				}

				loadPermissions();

				documentList.appendChild(item);


				
        });
    } catch (error) {
        listMessage.textContent = error.message;
    }
}


// Upload a document with the CSRF token.
uploadForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    uploadMessage.textContent = "";

    const title = document.getElementById("title").value.trim();
    const fileInput = document.getElementById("file");

    if (!title || !fileInput.files.length) {
        uploadMessage.textContent = "Enter a title and select a file.";
        return;
    }

    const csrfToken = getCsrfToken();

    if (!csrfToken) {
        uploadMessage.textContent =
            "Security token is missing. Refresh the page and try again.";
        return;
    }

    const formData = new FormData();
    formData.append("title", title);
    formData.append("file", fileInput.files[0]);
	formData.append(
	    "category",
	    document.getElementById("category").value
	);

    try {
        const response = await fetch("/api/documents", {
            method: "POST",
            credentials: "same-origin",
            headers: {
                "Accept": "application/json",
                "X-XSRF-TOKEN": csrfToken
            },
            body: formData
        });

        if (response.status === 401 || response.redirected) {
            window.location.href = "/login";
            return;
        }

        if (!response.ok) {
            const body = await response.text();
            throw new Error(
                `Upload failed (HTTP ${response.status}). ${body}`
            );
        }

        uploadMessage.textContent = "Document uploaded successfully.";
        uploadForm.reset();

        await loadDocuments();
    } catch (error) {
        uploadMessage.textContent = error.message;
    }
});

// Search documents when the search field changes.
documentSearch.addEventListener("input", () => {
    clearTimeout(searchTimer);

    searchTimer = setTimeout(() => {
        loadDocuments(documentSearch.value);
    }, 400);
});


// Start the dashboard.
loadDashboard();
